export function initAdminOperations({app,auth,db,data,esc,toast,showView}){
 const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],money=n=>Number(n||0).toLocaleString('ko-KR')+'원',paid=o=>['결제 완료','배송 준비','배송 중','배송 완료'].includes(o.status),stamp=v=>v?.toMillis?.()||(v?.seconds? v.seconds*1000:new Date(v||0).getTime()),date=v=>stamp(v)?new Date(stamp(v)).toLocaleString('ko-KR'):'-',empty=(n,t)=>`<tr><td colspan="${n}" class="empty-cell">${t}</td></tr>`;
 const invoke=httpsCallable(getFunctions(app,'asia-northeast3'),'adminOperations',{timeout:90000});
 let settings={storeName:'무드노트',email:'',phone:'',hours:'평일 10:00–17:00',description:'',shippingFee:3000,freeShippingThreshold:30000,dispatchDays:'결제 후 1–2영업일',carrier:'CJ대한통운'},coupons=[],usage=[],audits=[],stops=[],activeOrder=null,orderFilter='all',search='',galleryByForm=new WeakMap();
 const run=async(fn,button)=>{if(button)button.disabled=true;try{return await fn()}catch(e){toast(String(e.message||'처리하지 못했습니다.').replace(/^FirebaseError:\s*/,''));return null}finally{if(button?.isConnected)button.disabled=false}};
 async function action(payload){return (await invoke(payload)).data;}
 const safeURL=v=>{try{const u=new URL(v,location.href);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
 function panel(title,body){return `<article class="panel ops-panel"><h2>${title}</h2>${body}</article>`;}
 function insertView(id,title,body){$('.admin-main').insertAdjacentHTML('beforeend',`<section class="admin-view" data-view="${id}"><div class="page-head"><div><p>STORE OPERATIONS</p><h1>${title}</h1></div></div>${body}</section>`);}
 $('.admin-nav [data-admin-view="qna"]').insertAdjacentHTML('afterend','<button data-admin-view="support"><i>✉</i><span>1:1 문의</span><b id="nav-support-count">0</b></button>');
 $('.admin-nav').insertAdjacentHTML('beforeend','<button data-admin-view="audit"><i>≡</i><span>운영 변경 이력</span></button>');
 $('.top-actions').insertAdjacentHTML('beforeend','<button type="button" id="admin-logout">로그아웃</button>');
 $('.store-switch>button')?.remove();$('.sidebar-help').innerHTML='<small>판매자센터</small><strong>실제 데이터로 운영 중</strong><span>주문·재고·문의 실시간 반영</span>';
 $$('.table-footer>div').forEach(el=>el.remove());
 $$('[data-view="orders"] thead th:first-child,[data-view="products"] thead th:first-child').forEach(el=>el.textContent='');
 $('[data-view="dashboard"] .head-actions .primary').dataset.goView='product-create';
 $('[data-view="dashboard"] .kpi-grid').innerHTML=[['kpi-sales','결제완료 순매출'],['kpi-orders','결제완료 주문'],['kpi-average','평균 주문 금액'],['kpi-refunds','취소·환불 금액']].map(([id,title])=>`<article class="kpi-card"><span>${title}</span><strong id="${id}">0</strong><small>선택한 기간 기준</small></article>`).join('');
 $('.funnel-note')?.remove();$('.sales-panel .legend').innerHTML='<span><i class="red"></i>결제완료 금액</span>';$('.funnel-panel .panel-head p').textContent='전체 주문 기준';$('.sales-panel .panel-head p').textContent='선택한 기간의 일별 결제완료 금액';
 $('[data-view="marketing"] .marketing-grid').innerHTML=panel('쿠폰 목록','<p>회원 쿠폰함에 자동 표시됩니다. 사용 조건은 서버에서 검증하며, 한 계정당 한 번 사용할 수 있습니다.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>쿠폰·코드</th><th>혜택</th><th>기간</th><th>사용</th><th>상태</th><th>관리</th></tr></thead><tbody id="coupon-table"></tbody></table></div>');
 $('[data-view="settings"] .settings-grid').innerHTML=`<form id="ops-settings" class="panel ops-panel ops-fields">${[['storeName','쇼핑몰명'],['email','대표 이메일'],['phone','고객센터 연락처'],['hours','운영 시간'],['description','소개'],['dispatchDays','출고 안내'],['carrier','기본 택배사'],['shippingFee','기본 배송비 (원)','number'],['freeShippingThreshold','무료배송 기준 (원)','number']].map(([key,title,type])=>`<label>${title}<input name="${key}" type="${type||'text'}" ${type?'min="0" step="100"':''} ${key==='storeName'?'required':''}/></label>`).join('')}<p class="wide">배송 정책을 저장하면 새 주문의 배송비 계산과 쇼핑몰 안내에 적용됩니다.</p></form>`;
 $('#save-settings').setAttribute('form','ops-settings');$('#save-settings').type='submit';
 insertView('support','1:1 문의 관리',panel('고객센터 문의','<div class="table-scroll"><table class="data-table"><thead><tr><th>상태</th><th>제목·내용</th><th>고객·연락처</th><th>접수일</th><th>답변</th></tr></thead><tbody id="support-table"></tbody></table></div>'));
 insertView('audit','운영 변경 이력',panel('최근 변경 100건','<p>주문·환불·상품·쿠폰·운영 설정의 처리자와 시간을 기록합니다.</p><div class="table-scroll"><table class="data-table"><thead><tr><th>시각</th><th>처리자</th><th>작업</th><th>대상</th></tr></thead><tbody id="audit-table"></tbody></table></div>'));
 document.body.insertAdjacentHTML('beforeend','<dialog class="ops-dialog" id="ops-order-dialog" aria-labelledby="ops-order-title"></dialog><dialog class="ops-dialog" id="ops-coupon-dialog" aria-labelledby="ops-coupon-title"></dialog><dialog class="ops-dialog" id="ops-alert-dialog" aria-label="처리할 업무"></dialog>');
 function currentOrders(){return data().orders.filter(o=>(orderFilter==='all'||orderFilter==='claims'?orderFilter==='all'||!!o.claimStatus:o.status===orderFilter)&&(!search||[o.id,o.customer,o.phone,o.address?.recipient,...(o.items||[]).map(i=>i.name)].join(' ').toLowerCase().includes(search)));}
 $('#order-tabs').innerHTML=['전체','결제 완료','배송 준비','배송 중','배송 완료','승인 확인 중','취소·반품','주문 취소'].map((s,i)=>`<button data-ops-order-filter="${i===0?'all':s==='취소·반품'?'claims':s}" class="${i===0?'active':''}">${s}</button>`).join('');
 $('#order-search').placeholder='주문번호, 상품명, 주문자, 연락처';
 function renderOrders(){const all=data().orders,rows=currentOrders();$('#order-table').innerHTML=rows.map(o=>`<tr><td></td><td><button class="order-number" data-open-order="${esc(o.id)}">${esc(o.id)}</button><small class="cell-sub">${date(o.createdAt)}</small></td><td>${(o.items||[]).map(i=>`<div class="ops-order-line">${esc(i.name)}<small>${esc(i.option)} · ${i.quantity}개</small></div>`).join('')}</td><td>${esc(o.customer)}<small class="cell-sub">${o.guest?'비회원':'회원'}</small></td><td>${money(o.total)}</td><td><span class="status-badge">${esc(o.status)}</span>${o.claimStatus?`<small class="cell-sub">${esc(o.claimStatus)}</small>`:''}</td><td><button class="row-action" data-open-order="${esc(o.id)}">상세·처리</button></td></tr>`).join('')||empty(7,'조건에 맞는 주문이 없습니다.');$('#order-result-count').textContent=`총 ${rows.length}건`;$$('[data-view="orders"] .summary-row strong').forEach((el,i)=>el.textContent=all.filter(o=>o.status===['결제 완료','배송 준비','배송 중','배송 완료'][i]).length);}
 function renderDashboard(){const all=data().orders,days=Number($('#period-select').value||30),now=Date.now(),start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-days+1);const subset=all.filter(o=>stamp(o.approvedAt||o.createdAt)>=start.getTime()),completed=subset.filter(paid),sales=completed.reduce((s,o)=>s+Number(o.total||0),0);$('#kpi-sales').textContent=money(sales);$('#kpi-orders').textContent=completed.length+'건';$('#kpi-average').textContent=money(completed.length?Math.round(sales/completed.length):0);$('#kpi-refunds').textContent=money(subset.reduce((s,o)=>s+Number(o.refundedAmount||0),0));const waiting=all.filter(o=>['결제 완료','배송 준비','승인 확인 중'].includes(o.status));$('#nav-order-count').textContent=waiting.length;
  const statuses=['결제 완료','배송 준비','배송 중','배송 완료'];$('.funnel-list').innerHTML=statuses.map(s=>{const n=all.filter(o=>o.status===s).length;return `<div><span>${s}</span><b>${n}</b><i style="--w:${all.length?n/all.length*100:0}%"></i></div>`}).join('');
  const tasks=[all.filter(o=>o.status==='결제 완료').length,all.filter(o=>o.status==='배송 준비').length,all.filter(o=>o.claimStatus&&!['환불 완료','처리 종료'].includes(o.claimStatus)).length,data().adminProducts.filter(p=>p.stock<=8).length];$$('.action-strip strong').forEach((el,i)=>el.textContent=tasks[i]);$$('.action-strip small').forEach((el,i)=>el.textContent=['상품 준비 대기','송장 등록 대기','미처리 요청','8개 이하 상품'][i]);
  const buckets=Array(days).fill(0);completed.forEach(o=>{const d=new Date(stamp(o.approvedAt||o.createdAt));d.setHours(0,0,0,0);const idx=Math.round((d-start)/86400000);if(idx>=0&&idx<days)buckets[idx]+=Number(o.total||0)});const max=Math.max(1,...buckets);$('#sales-chart').innerHTML=buckets.map((v,i)=>`<div class="chart-day" title="${new Date(start.getTime()+i*86400000).toLocaleDateString('ko-KR')}: ${money(v)}"><i style="--h:${v/max*100}%"></i><span>${i===0?`${days}일`:i===days-1?'오늘':''}</span></div>`).join('');$('.y-axis').innerHTML=[1,.75,.5,.25,0].map(n=>`<span>${Math.round(max*n).toLocaleString()}</span>`).join('');
  $('#dashboard-orders').innerHTML=all.slice(0,5).map(o=>`<tr><td><button class="order-number" data-open-order="${esc(o.id)}">${esc(o.id)}</button></td><td>${esc(o.items?.[0]?.name||'-')}${o.items?.length>1?` 외 ${o.items.length-1}건`:''}</td><td>${esc(o.customer)}</td><td>${money(o.total)}</td><td>${esc(o.status)}</td></tr>`).join('')||empty(5,'아직 주문이 없습니다.');
  renderAlerts();}
 function renderAlerts(){const count=data().qna.filter(q=>q.status==='waiting').length+data().orders.filter(o=>['결제 완료','승인 확인 중'].includes(o.status)).length;$('.notification b').textContent=count;$('.notification').setAttribute('aria-label',`처리할 업무 ${count}건`);renderSummaries();}
 function renderSummaries(){const {qna,reviews,customers,orders,adminProducts}=data(),now=Date.now(),q=qna.filter(q=>q.productId!=='support'),today=new Date().toDateString(),recent=reviews.filter(r=>now-stamp(r.createdAt)<30*86400000),average=recent.length?recent.reduce((s,r)=>s+Number(r.rating),0)/recent.length:0;
  const vals=[q.filter(v=>v.status==='waiting').length,q.filter(v=>new Date(stamp(v.createdAt)).toDateString()===today).length,q.filter(v=>v.status==='done').length,q.filter(v=>v.secret).length];$$('[data-view="qna"] .summary-row strong').forEach((el,i)=>el.textContent=vals[i]);$$('[data-view="qna"] .summary-row article span')[3].textContent='비밀 문의';$('.review-score strong').textContent=recent.length?average.toFixed(1):'-';$('.review-score small').textContent=`최근 30일 ${recent.length}개 리뷰`;$('.review-score>div').textContent=recent.length?'★'.repeat(Math.round(average)):'리뷰 없음';$$('.rating-bars>div').forEach((el,i)=>{const n=recent.filter(r=>r.rating===5-i).length;el.querySelector('em').textContent=n;el.querySelector('b').style.setProperty('--w',(recent.length?n/recent.length*100:0)+'%')});$$('.review-summary strong')[1].textContent=reviews.filter(r=>r.photo).length;
  const counts=[0,0,0,0];for(const c of customers){const p=orders.filter(o=>o.userId===c.uid&&paid(o)),last=Math.max(0,...p.map(o=>stamp(o.approvedAt||o.createdAt)));if(p.length>=3)counts[0]++;if(now-stamp(c.createdAt)<=30*86400000)counts[1]++;if(last&&now-last>30*86400000&&now-last<=60*86400000)counts[2]++;if(last&&now-last>90*86400000)counts[3]++;}$$('.customer-segments strong').forEach((el,i)=>el.textContent=counts[i]+'명');$$('[data-view="products"] .summary-row strong')[3].textContent=adminProducts.filter(p=>p.stock<=0||p.saleStatus==='품절').length;
 }
 function renderSupport(){const rows=data().qna.filter(q=>q.productId==='support');$('#support-table').innerHTML=rows.map(q=>`<tr><td>${q.status==='done'?'답변 완료':'답변 대기'}</td><td><strong>${esc(q.title)}</strong><p>${esc(q.content)}</p></td><td>${esc(q.customer)}<small class="cell-sub">${esc(q.email||'')} ${esc(q.phone||'')}</small></td><td>${date(q.createdAt)}</td><td><button class="care-button" data-qna-reply="${esc(q.id)}">${q.answer?'답변 수정':'답변하기'}</button></td></tr>`).join('')||empty(5,'접수된 문의가 없습니다.');$('#nav-support-count').textContent=rows.filter(q=>q.status==='waiting').length;$('.admin-nav [data-admin-view="qna"] b').textContent=data().qna.filter(q=>q.productId!=='support'&&q.status==='waiting').length;renderAlerts();}
 function openOrder(id){const o=data().orders.find(o=>o.id===id);if(!o)return;activeOrder=id;const a=o.address||{},dialog=$('#ops-order-dialog'),next={'결제 완료':'배송 준비','배송 준비':'배송 중','배송 중':'배송 완료'}[o.status];dialog.innerHTML=`<header><div><small>ORDER DETAIL</small><h2 id="ops-order-title">${esc(o.id)}</h2><span>${esc(o.status)} · ${date(o.createdAt)}</span></div><button data-ops-close aria-label="주문 상세 닫기">×</button></header><div class="ops-dialog-body"><div class="ops-detail-grid">${panel('주문자',`<p>${esc(o.customer)} · ${o.guest?'비회원':'회원'}</p><p>${esc(o.phone)}<br/>${esc(o.userEmail)}</p>`)}${panel('배송지',`<p>${esc(a.recipient)} · ${esc(a.recipientPhone)}</p><p>[${esc(a.zip)}] ${esc(a.address)}<br/>${esc(a.address2)}</p><p>배송 메모: ${esc(a.memo||'없음')}</p>`)}</div>${panel('주문 상품',(o.items||[]).map(i=>`<div class="ops-item"><img src="${esc(safeURL(i.image))}" alt=""/><div><b>${esc(i.name)}</b><p>${esc(i.option)} · ${i.quantity}개</p></div><strong>${money(i.price*i.quantity)}</strong></div>`).join('')+`<div class="ops-totals"><span>상품 ${money(o.subtotal)} + 배송 ${money(o.shipping)} − 할인 ${money(o.discount)}</span><strong>결제 ${money(o.total)}</strong></div>`)}${o.customText||o.customUploads?.length?panel('주문제작 요청',`<p>${esc(o.customText)}</p>${(o.customUploads||[]).map(f=>`<a href="${esc(safeURL(f.url))}" target="_blank" rel="noopener noreferrer">${esc(f.name||'첨부 이미지')} ↗</a>`).join('<br/>')}`):''}
  <form id="ops-order-form" class="panel ops-panel ops-fields"><h2 class="wide">배송·처리 정보</h2><label>택배사<input name="carrier" value="${esc(o.carrier||settings.carrier)}"/></label><label>송장번호<input name="trackingNumber" value="${esc(o.trackingNumber||'')}" placeholder="운송장 번호"/></label><label>요청 처리<select name="claimStatus">${['','반품 접수','회수 완료','교환 접수','교환 재발송','처리 종료'].map(s=>`<option value="${s}"${o.claimStatus===s?' selected':''}>${s||'요청 없음'}</option>`).join('')}</select></label><label>요청 사유<input name="claimReason" maxlength="300" value="${esc(o.claimReason||'')}"/></label><label class="wide">운영자 메모<textarea name="memo" rows="3" maxlength="2000">${esc(o.adminMemo||'')}</textarea></label><div class="wide ops-actions"><button class="secondary" type="submit">배송·메모 저장</button>${next?`<button class="primary" type="button" data-next-status="${next}">${next==='배송 중'?'송장 등록 후 발송':next+' 처리'}</button>`:''}<button class="secondary" type="button" data-reconcile>결제 상태 확인</button>${o.receiptUrl?`<a href="${esc(safeURL(o.receiptUrl))}" target="_blank" rel="noopener noreferrer">결제 영수증 ↗</a>`:''}</div></form>
  ${o.paymentKey&&o.status!=='주문 취소'?`<details class="panel ops-panel"><summary>취소·전액 환불</summary><p>토스 결제 전체 금액 ${money(o.total)}을 취소합니다. 반품 상품은 회수 상태를 확인한 뒤 처리해주세요.</p><p>${o.inventoryState==='committed'||o.inventoryState==='reserved'?'재고 복원 여부를 선택할 수 있습니다.':'이전 주문은 자동 차감 이력이 없어 재고를 자동 복원하지 않습니다.'}</p><form id="ops-refund-form"><label>환불 사유<textarea name="reason" required maxlength="300" rows="2">${esc(o.cancelRequest?.reason||'')}</textarea></label><label class="ops-check"><input type="checkbox" name="restock" ${o.cancelRequest?.restock?'checked':''}/> 회수·미발송 상품을 판매 재고로 복원</label><label class="ops-check"><input type="checkbox" required/> 주문과 금액을 확인했으며 전액 환불에 동의합니다.</label><button class="danger" type="submit">${money(o.total)} 전액 환불 실행</button></form></details>`:''}</div>`;if(!dialog.open)dialog.showModal();}
 async function updateOrder(form,status){const d=Object.fromEntries(new FormData(form));await action({action:'updateOrder',orderId:activeOrder,...d,...(status?{status}:{})});toast('주문 처리 내용을 저장했습니다.');$('#ops-order-dialog').close();}
 function couponEditor(code){const c=coupons.find(c=>c.code===code)||{code:'',name:'',type:'percent',value:10,minSpend:0,maxDiscount:0,startDate:new Date().toLocaleDateString('en-CA'),endDate:'',enabled:true,firstOrder:false};const dialog=$('#ops-coupon-dialog');dialog.innerHTML=`<header><h2 id="ops-coupon-title">${code?'쿠폰 수정':'쿠폰 만들기'}</h2><button data-ops-close aria-label="쿠폰 편집 닫기">×</button></header><form id="ops-coupon-form" class="ops-dialog-body ops-fields"><label>쿠폰 코드<input name="code" required pattern="[A-Za-z0-9_-]{3,40}" value="${esc(c.code)}" ${code?'readonly':''}/></label><label>쿠폰명<input name="name" required maxlength="80" value="${esc(c.name)}"/></label><label>할인 방식<select name="type"><option value="percent"${c.type==='percent'?' selected':''}>정률 (%)</option><option value="amount"${c.type==='amount'?' selected':''}>정액 (원)</option></select></label><label>할인 값<input name="value" type="number" min="1" required value="${c.value}"/></label><label>최소 구매금액<input name="minSpend" type="number" min="0" value="${c.minSpend}"/></label><label>최대 할인 (0: 제한 없음)<input name="maxDiscount" type="number" min="0" value="${c.maxDiscount}"/></label><label>시작일<input name="startDate" type="date" required value="${esc(c.startDate)}"/></label><label>종료일<input name="endDate" type="date" required value="${esc(c.endDate)}"/></label><label class="ops-check"><input name="firstOrder" type="checkbox" ${c.firstOrder?'checked':''}/> 첫 주문에만 사용</label><label class="ops-check"><input name="enabled" type="checkbox" ${c.enabled?'checked':''}/> 회원에게 공개</label><p class="wide">회원 쿠폰함에 표시되며 계정당 1회 사용할 수 있습니다. 이미 사용한 쿠폰을 수정해도 다시 지급되지 않습니다.</p><button class="primary wide" type="submit">쿠폰 저장</button></form>`;dialog.showModal();}
 function renderCoupons(){$('#coupon-table').innerHTML=coupons.map(c=>`<tr><td><b>${esc(c.name)}</b><small class="cell-sub">${esc(c.code)}</small></td><td>${c.type==='percent'?c.value+'%':money(c.value)}<small class="cell-sub">${c.firstOrder?'첫 주문 전용':'전체 회원'}</small></td><td>${esc(c.startDate)} ~ ${esc(c.endDate)}</td><td>${usage.filter(u=>u.code===c.code&&u.status==='used').length}회</td><td>${c.enabled?'공개':'중지'}</td><td><button class="row-action" data-edit-coupon="${esc(c.code)}">수정</button></td></tr>`).join('')||empty(6,'등록한 쿠폰이 없습니다.');}
 function addProductFields(form){const creating=form.id==='product-create-form';form.querySelector('.edit-main').insertAdjacentHTML('beforeend',panel('이미지·옵션·사양',`<div class="ops-fields"><label class="wide">대표 이미지 주소<input name="opsImage" required placeholder="https://... 또는 assets/..."/></label><label>대표 이미지 업로드<input type="file" accept="image/png,image/jpeg,image/webp" data-upload-main/></label><label>정가<input name="opsOriginal" type="number" min="0" step="100"/></label><label class="wide">옵션과 재고 (한 줄에 옵션명 | 수량)<textarea name="opsOptions" rows="5" placeholder="체리 레드 | 10&#10;크림 | 20" required></textarea><small>수량을 모두 생략하면 상품 공통 재고를 사용합니다. 옵션별 수량을 입력하면 합계가 전체 재고가 됩니다.</small></label><label class="wide">크기·구성·소재 (항목: 내용)<textarea name="opsSpec" rows="4"></textarea></label></div><h3>상세 이미지 갤러리</h3><p>대표 이미지 다음에 표시할 사진을 순서대로 추가하세요. 최대 12장입니다.</p><div class="ops-gallery"></div><div class="ops-actions"><button type="button" class="secondary" data-gallery-add>이미지 주소 추가</button><label class="secondary">사진 업로드<input type="file" multiple accept="image/png,image/jpeg,image/webp" data-upload-gallery/></label></div>`));galleryByForm.set(form,[]);form.elements.opsOptions.value='기본 옵션';form.querySelector('.editor-toolbar')?.remove();form.querySelector('.content-blocks')?.remove();form.querySelector('#add-content-block')?.remove();if(creating){for(const name of ['image','options','spec','originalPrice']){const el=form.elements[name];if(el){el.required=false;el.closest('label').hidden=true;}}}form.querySelector('.detail-editor-label')?.insertAdjacentHTML('beforebegin','<p class="ops-help">설명은 문단 단위로 입력하고, 활용 사진과 순서는 아래 갤러리에서 편집하세요.</p>');}
 const forms=[$('#product-create-form'),$('#product-edit-form')];forms.forEach(addProductFields);
 function gallery(form){const list=galleryByForm.get(form)||[];form.querySelector('.ops-gallery').innerHTML=list.map((g,i)=>`<div class="ops-gallery-row"><img src="${esc(safeURL(g.src))}" alt="미리보기"/><label>설명<input data-gallery-label="${i}" maxlength="100" value="${esc(g.label)}"/></label><label>이미지 주소<input data-gallery-src="${i}" value="${esc(g.src)}"/></label><div><button type="button" data-gallery-move="${i}" data-step="-1" aria-label="이미지 위로" ${i===0?'disabled':''}>↑</button><button type="button" data-gallery-move="${i}" data-step="1" aria-label="이미지 아래로" ${i===list.length-1?'disabled':''}>↓</button><button type="button" data-gallery-remove="${i}">삭제</button></div></div>`).join('');}
 function fillProduct(p){const form=$('#product-edit-form');form.dataset.expectedUpdatedAt=p.updatedAt?.toMillis?.()||'';form.elements.opsImage.value=p.image||'';form.elements.opsOriginal.value=p.originalPrice||p.original||0;form.elements.opsOptions.value=(p.options||['기본 옵션']).map(o=>o+(p.variantStock?' | '+(p.variantStock[o]||0):'')).join('\n');form.elements.opsSpec.value=Object.entries(p.spec||{}).map(([k,v])=>`${k}: ${v}`).join('\n');galleryByForm.set(form,(p.gallery||defaultGallery[p.id]||[]).filter(g=>g.src!==p.image).map(g=>({...g})));gallery(form);}
 async function saveProduct(form,create=false){const rows=form.elements.opsOptions.value.split('\n').map(s=>s.trim()).filter(Boolean),options=[],variantStock={};let hasStock=false,missing=false;for(const row of rows){const [name,qty,...rest]=row.split('|').map(s=>s.trim());if(rest.length)throw Error('옵션 형식은 옵션명 | 수량입니다.');options.push(name);if(qty!==undefined&&qty!==''){if(!/^\d+$/.test(qty))throw Error('옵션 재고는 0 이상의 정수로 입력해주세요.');hasStock=true;variantStock[name]=Number(qty)}else missing=true;}if(hasStock&&missing)throw Error('모든 옵션의 재고를 입력하거나 모두 생략해주세요.');const p={id:create?form.elements.slug.value:form.dataset.productId,name:form.elements.name.value,maker:form.elements.maker.value,category:form.elements.category.value,price:Number(form.elements.price.value),stock:Number(form.elements.stock.value),saleStatus:form.elements.saleStatus.value,badge:form.elements.badge.value,description:form.elements.summary.value,detail:form.elements.detail.value,image:form.elements.opsImage.value,originalPrice:Number(form.elements.opsOriginal.value||0),options,variantStock:hasStock?variantStock:null,gallery:galleryByForm.get(form)||[],spec:Object.fromEntries(form.elements.opsSpec.value.split('\n').filter(v=>v.includes(':')).map(v=>{const i=v.indexOf(':');return [v.slice(0,i).trim(),v.slice(i+1).trim()]}))};for(const name of ['searchVisible','featured','reviewEnabled','qnaEnabled'])p[name]=form.elements[name].checked;await action({action:'saveProduct',product:p,create,expectedUpdatedAt:Number(form.dataset.expectedUpdatedAt)||null});toast(create?'상품을 등록했습니다.':'상품과 상세페이지를 저장했습니다.');if(create){form.reset();galleryByForm.set(form,[]);gallery(form);}showView('products');}
 async function upload(input,main){const form=input.closest('form'),files=[...input.files];if(!files.length)return;if(!main&&(galleryByForm.get(form).length+files.length)>12)throw Error('상세 이미지는 최대 12장입니다.');for(const file of main?files.slice(0,1):files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>=10*1024*1024)throw Error('10MB 미만의 PNG, JPEG, WebP 이미지를 선택해주세요.');const id=form.dataset.productId||form.elements.slug?.value||'draft',target=ref(getStorage(app),`product-media/${id}/${crypto.randomUUID()}`);await uploadBytes(target,file,{contentType:file.type});const url=await getDownloadURL(target);if(main){form.elements.opsImage.value=url;form.querySelector('#edit-product-image')?.setAttribute('src',url)}else galleryByForm.get(form).push({src:url,label:file.name.replace(/\.[^.]+$/,'')});}gallery(form);input.value='';toast('사진을 올렸습니다. 상품을 저장하면 반영됩니다.');}
 document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.matches('[data-ops-close]')){target.closest('dialog').close();return;}if(target.dataset.openOrder){openOrder(target.dataset.openOrder);return;}if(target.dataset.opsOrderFilter){orderFilter=target.dataset.opsOrderFilter;$$('[data-ops-order-filter]').forEach(b=>b.classList.toggle('active',b===target));renderOrders();return;}if(target.id==='admin-logout'){run(()=>signOut(auth),target);return;}if(target.id==='add-coupon'){couponEditor();return;}if(target.dataset.editCoupon){couponEditor(target.dataset.editCoupon);return;}if(target.matches('.notification')){const d=$('#ops-alert-dialog');d.innerHTML=`<header><h2>처리할 업무</h2><button data-ops-close aria-label="알림 닫기">×</button></header><div class="ops-dialog-body"><p>결제 완료·확인 대기 ${data().orders.filter(o=>['결제 완료','승인 확인 중'].includes(o.status)).length}건</p><p>답변 대기 문의 ${data().qna.filter(q=>q.status==='waiting').length}건</p><div class="ops-actions"><button data-go-view="orders" data-ops-close class="primary">주문 처리</button><button data-go-view="support" data-ops-close class="secondary">1:1 문의</button><button data-go-view="qna" data-ops-close class="secondary">상품 문의</button></div></div>`;d.showModal();return;}if(target.dataset.nextStatus){const form=$('#ops-order-form');if(form.reportValidity())run(()=>updateOrder(form,target.dataset.nextStatus),target);return;}if(target.hasAttribute('data-reconcile')){run(async()=>{const r=await action({action:'reconcile',orderId:activeOrder});toast(r.message||`결제 상태: ${r.status}`);$('#ops-order-dialog').close();},target);return;}
  const form=target.closest('#product-edit-form,#product-create-form');if(!form)return;const list=galleryByForm.get(form);if(target.hasAttribute('data-gallery-add')){if(list.length>=12){toast('최대 12장입니다.');return}list.push({src:'',label:''});gallery(form);}if(target.hasAttribute('data-gallery-remove')){list.splice(Number(target.dataset.galleryRemove),1);gallery(form);}if(target.hasAttribute('data-gallery-move')){const i=Number(target.dataset.galleryMove),j=i+Number(target.dataset.step);if(j>=0&&j<list.length)[list[i],list[j]]=[list[j],list[i]];gallery(form);}
 });
 document.addEventListener('input',e=>{if(e.target.id==='order-search'){search=e.target.value.trim().toLowerCase();renderOrders();}const form=e.target.closest('#product-edit-form,#product-create-form');if(form&&e.target.hasAttribute('data-gallery-label'))galleryByForm.get(form)[Number(e.target.dataset.galleryLabel)].label=e.target.value;if(form&&e.target.hasAttribute('data-gallery-src'))galleryByForm.get(form)[Number(e.target.dataset.gallerySrc)].src=e.target.value;});
 document.addEventListener('change',e=>{if(e.target.id==='period-select')renderDashboard();if(e.target.hasAttribute('data-upload-main'))run(()=>upload(e.target,true),e.target);if(e.target.hasAttribute('data-upload-gallery'))run(()=>upload(e.target,false),e.target);});
 document.addEventListener('submit',e=>{const form=e.target,button=e.submitter;if(!['ops-settings','ops-coupon-form','ops-order-form','ops-refund-form'].includes(form.id))return;e.preventDefault();run(async()=>{if(form.id==='ops-settings'){await action({action:'saveSettings',settings:Object.fromEntries(new FormData(form))});toast('운영 설정을 저장했습니다.');}if(form.id==='ops-coupon-form'){const coupon=Object.fromEntries(new FormData(form));coupon.enabled=form.elements.enabled.checked;coupon.firstOrder=form.elements.firstOrder.checked;await action({action:'saveCoupon',coupon});$('#ops-coupon-dialog').close();toast('쿠폰을 저장했습니다.');}if(form.id==='ops-order-form')await updateOrder(form);if(form.id==='ops-refund-form'){await action({action:'refund',orderId:activeOrder,reason:form.elements.reason.value,restock:form.elements.restock.checked});toast('결제사 전액 취소를 확인했습니다.');$('#ops-order-dialog').close();}},button);});
 function stop(){stops.forEach(stop=>stop());stops=[];coupons=[];usage=[];audits=[];$$('.ops-dialog[open],.admin-dialog[open]').forEach(d=>d.close());renderCoupons();$('#audit-table').innerHTML=empty(4,'운영자로 로그인해주세요.');}
 function listen(){stop();const watch=(target,fn)=>stops.push(onSnapshot(target,fn,e=>toast('운영 데이터를 불러오지 못했습니다: '+e.code)));watch(doc(db,'storefront','public'),snap=>{settings={...settings,...snap.data()};for(const [key,value] of Object.entries(settings)){const el=$('#ops-settings').elements[key];if(el)el.value=value;}});watch(collection(db,'coupons'),snap=>{coupons=snap.docs.map(d=>d.data());renderCoupons()});watch(collection(db,'couponUsage'),snap=>{usage=snap.docs.map(d=>d.data());renderCoupons()});watch(query(collection(db,'adminAudit'),orderBy('createdAt','desc'),limit(100)),snap=>{audits=snap.docs.map(d=>d.data());$('#audit-table').innerHTML=audits.map(a=>`<tr><td>${date(a.createdAt)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td>${esc(a.target)}</td></tr>`).join('')||empty(4,'아직 변경 이력이 없습니다.');});}
 $('#qna-template-button').remove();$('[data-view="reviews"] .page-head>button').remove();$('[data-view="customers"] .page-head>button').remove();
 const customerSearch=$('[data-view="customers"] input[type="search"]');customerSearch.addEventListener('input',()=>{const term=customerSearch.value.toLowerCase();$$('#customer-table tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(term));});
 return {renderOrders,renderDashboard,renderSupport,fillProduct,saveProduct,listen,stop,run,openOrder,renderAlerts,renderSummaries};
}
